SELECT CAST(sm.message_id AS CHAR) AS messageId, sm.group_type AS groupType, sm.title AS title, sm.content AS content, sm.related_type AS relatedType, CAST(sm.related_id AS CHAR) AS relatedId, sm.priority AS priority, CASE WHEN smr.id IS NULL THEN FALSE ELSE TRUE END AS isRead, DATE_FORMAT(sm.created_at, '%Y-%m-%d %H:%i') AS createdAt FROM system_message sm LEFT JOIN system_message_read smr ON smr.message_id = sm.message_id AND smr.user_id = #{userId} AND smr.is_read = 1 WHERE sm.camp_id = #{campId} AND sm.status = 1
AND sm.group_type = #{groupType}
ORDER BY sm.created_at DESC, sm.message_id DESC

SELECT COUNT(1)
FROM system_message sm
LEFT JOIN system_message_read smr ON smr.message_id = sm.message_id
    AND smr.user_id = #{userId}
    AND smr.is_read = 1
WHERE sm.camp_id = #{campId}
  AND sm.status = 1

    AND sm.group_type = #{groupType}

  AND smr.id IS NULL

SELECT sm.message_id
FROM system_message sm
LEFT JOIN system_message_read smr ON smr.message_id = sm.message_id
    AND smr.user_id = #{userId}
    AND smr.is_read = 1
WHERE sm.camp_id = #{campId}
  AND sm.status = 1

    AND sm.group_type = #{groupType}

  AND smr.id IS NULL
